/**
 * The baseline: one SQL file that builds, on an EMPTY database, the schema
 * that migrations 0001..N built, plus the ledger those migrations wrote.
 *
 *   db/baseline/NNNN_baseline.sql   generated by scripts/baseline.sh generate
 *   db/baseline/ledger.tsv          version, name, checksum of 0001..NNNN
 *
 * A database migrated file by file before the baseline existed holds the
 * same ledger rows, so it is at head without the baseline ever running on it.
 * An empty database gets the baseline and all of those rows in one
 * transaction.
 *
 * CARRIED files: the newest versions of the baseline may also ship as files
 * in db/migrations, under the same name and with the checksum ledger.tsv
 * records for them, as a contiguous run ending at the head. They are how a
 * database that stopped just before the head reaches it: a ledger holding
 * exactly 1..k, with every version k+1..N carried, gets those files applied
 * in order and ends with the same ledger an empty database gets from the
 * baseline. Any other database holding SOME of 0001..N is refused: the
 * baseline cannot finish a half-built schema.
 *
 * The baseline's versions take part in readiness like files do. Each row of
 * ledger.tsv becomes an entry with `baseline: true` and the original
 * checksum, so a database whose ledger disagrees with the baseline is a
 * MISMATCH, exactly as an edited file would be.
 */
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { MIGRATION_FILE, readMigrations, sha256Hex, versionOf, type MigrationFile } from "./files.js";

export const LEDGER_TSV = "ledger.tsv";
export const LEDGER_HEADER = "version\tname\tchecksum";
export const BASELINE_FILE = /^[0-9]{4}_baseline\.sql$/;

export class BaselineError extends Error {}

export type Baseline = {
  /** The highest version the baseline stands for. */
  readonly head: number;
  /** The baseline file's name, e.g. `0293_baseline.sql`. */
  readonly name: string;
  readonly bytes: Buffer;
  /** SHA-256 of the baseline file (reported, never written to the ledger). */
  readonly checksum: string;
  /** One entry per ledger.tsv row, in version order, each `baseline: true`. */
  readonly entries: readonly MigrationFile[];
  /** The files that carry the baseline's newest versions (see the header), in version order; set by assembleSchema. */
  readonly carried?: readonly MigrationFile[];
};

export type Schema = {
  readonly baseline: Baseline | null;
  /** The files after the baseline. */
  readonly files: readonly MigrationFile[];
  /** Baseline entries then files: what readiness compares the ledger with. */
  readonly all: readonly MigrationFile[];
};

export type LedgerRow = { readonly version: number; readonly name: string; readonly checksum: string };

/** ledger.tsv → rows. Every rule is a refusal: a ledger we cannot trust must not be written into a database. */
export function parseLedgerTsv(text: string): LedgerRow[] {
  const lines = text.split("\n");
  if (lines[lines.length - 1] === "") lines.pop();
  if (lines[0] !== LEDGER_HEADER) throw new BaselineError(`${LEDGER_TSV}: the first line must be '${LEDGER_HEADER.replace(/\t/g, "\\t")}'`);
  const rows: LedgerRow[] = [];
  for (let i = 1; i < lines.length; i += 1) {
    const cols = (lines[i] ?? "").split("\t");
    const where = `${LEDGER_TSV} line ${String(i + 1)}`;
    if (cols.length !== 3) throw new BaselineError(`${where}: expected 3 tab-separated columns, got ${String(cols.length)}`);
    const [v = "", name = "", checksum = ""] = cols;
    if (!/^[1-9][0-9]*$/.test(v)) throw new BaselineError(`${where}: the version must be a positive whole number`);
    const version = Number(v);
    if (version !== i) throw new BaselineError(`${where}: expected version ${String(i)} (contiguous from 1, no gaps, no duplicates), got ${v}`);
    if (!MIGRATION_FILE.test(name) || /[\s']/.test(name) || versionOf(name) !== version) throw new BaselineError(`${where}: '${name.slice(0, 80)}' is not a migration name for version ${v}`);
    if (!/^[0-9a-f]{64}$/.test(checksum)) throw new BaselineError(`${where}: the checksum must be 64 lower-case hex characters`);
    rows.push({ version, name, checksum });
  }
  if (rows.length === 0) throw new BaselineError(`${LEDGER_TSV}: no rows`);
  return rows;
}

/** A ledger row as an entry readiness can compare: the original name and checksum, no bytes of its own. */
export function baselineEntry(r: LedgerRow): MigrationFile {
  return { name: r.name, version: r.version, checksum: r.checksum, noTransaction: false, bytes: Buffer.alloc(0), baseline: true };
}

/** The baseline in `dir`, or null when the directory does not exist (an image built without one). */
export function readBaseline(dir: string): Baseline | null {
  if (!existsSync(dir)) return null;
  const names = readdirSync(dir);
  const sql = names.filter((n) => BASELINE_FILE.test(n));
  const stray = names.filter((n) => n !== LEDGER_TSV && !BASELINE_FILE.test(n) && !n.startsWith("."));
  if (stray.length > 0) throw new BaselineError(`${dir}: unexpected file(s) ${stray.join(", ")}; only ${LEDGER_TSV} and one NNNN_baseline.sql belong here`);
  if (sql.length !== 1) throw new BaselineError(`${dir}: expected exactly one NNNN_baseline.sql, found ${String(sql.length)}`);
  if (!names.includes(LEDGER_TSV)) throw new BaselineError(`${dir}: ${LEDGER_TSV} is missing`);
  const rows = parseLedgerTsv(readFileSync(join(dir, LEDGER_TSV), "utf8"));
  const name = sql[0] ?? "";
  const head = rows.length;
  if (versionOf(name) !== head) throw new BaselineError(`${dir}: ${name} must be numbered ${String(head).padStart(4, "0")}, the last version in ${LEDGER_TSV}`);
  const bytes = readFileSync(join(dir, name));
  if (bytes.length === 0) throw new BaselineError(`${dir}: ${name} is empty`);
  return { head, name, bytes, checksum: sha256Hex(bytes), entries: rows.map(baselineEntry), carried: [] };
}

/**
 * The files at or below a baseline's head, judged: each must be a carried
 * file (its name and checksum equal to its ledger.tsv row) and together they
 * must run without a gap up to the head. Returns the reason for the first one
 * that is not, or null.
 */
export function carriedFault(head: number, rows: readonly Pick<LedgerRow, "version" | "name" | "checksum">[], carried: readonly Pick<MigrationFile, "version" | "name" | "checksum">[]): string | null {
  const next = String(head + 1).padStart(4, "0");
  for (const f of carried) {
    const r = rows[f.version - 1];
    if (r === undefined || r.name !== f.name) return `${f.name}: the baseline already stands for versions 1..${String(head)} and ${LEDGER_TSV} names version ${String(f.version)} ${r?.name ?? "(none)"}; migrations after it start at ${next}`;
    if (r.checksum !== f.checksum) return `${f.name}: the baseline carries version ${String(f.version)} with another checksum in ${LEDGER_TSV} — a carried file is the exact file the baseline was generated from; never edit it`;
  }
  const first = carried[0]?.version ?? head + 1;
  for (let k = 0; k < carried.length; k += 1) {
    if (carried[k]?.version !== first + k || first + carried.length - 1 !== head) {
      return `${carried[k]?.name ?? "?"}: carried files must run without a gap up to the baseline's head ${String(head).padStart(4, "0")}`;
    }
  }
  return null;
}

/** The baseline and the files after it. A file at or below the baseline's head must be a carried file (see the header); anything else is two sources for one version. */
export function assembleSchema(baseline: Baseline | null, files: readonly MigrationFile[]): Schema {
  if (baseline === null) return { baseline, files, all: [...files] };
  const carried = files.filter((f) => f.version <= baseline.head);
  const after = files.filter((f) => f.version > baseline.head);
  const fault = carriedFault(
    baseline.head,
    baseline.entries.map((e) => ({ version: e.version, name: e.name, checksum: e.checksum })),
    carried,
  );
  if (fault !== null) throw new BaselineError(fault);
  const b: Baseline = { ...baseline, carried };
  return { baseline: b, files: after, all: [...b.entries, ...after] };
}

export function loadSchema(migrationsDir: string, baselineDir: string): Schema {
  const files = existsSync(migrationsDir) || baselineDir === "" || !existsSync(baselineDir) ? readMigrations(migrationsDir) : [];
  return assembleSchema(readBaseline(baselineDir), files);
}

/**
 * What psql is sent for the baseline, in one transaction: the dump, then the
 * search path the dump cleared put back, then one ledger insert per row.
 * The bare "\n" after the dump is the same guard as a wrapped file's.
 */
export function baselineScript(b: Baseline, insert: (f: MigrationFile) => string): Buffer {
  const rows = b.entries.map((e) => insert(e)).join("\n");
  return Buffer.concat([Buffer.from("begin;\n"), b.bytes, Buffer.from(`\nreset search_path;\n${rows}\ncommit;\n`)]);
}

/**
 * A ledger exported from a database (`version, name, checksum`, tab- or
 * `|`-separated, the header optional) against the baseline's ledger.tsv.
 * Read-only: it names every version the export lacks, names differently or
 * holds with another checksum. Versions after the baseline are counted, not
 * compared (they belong to the migrations after it).
 */
export function compareLedgerExport(b: Baseline, exportText: string): { exitCode: number; lines: string[] } {
  const rows = new Map<number, { name: string; checksum: string }>();
  const lines = exportText.replace(/\r\n/g, "\n").split("\n");
  lines.forEach((raw, k) => {
    const l = raw.trim();
    if (l === "" || (k === 0 && /^version[\t|]name[\t|]checksum$/.test(l))) return;
    const cols = l.split(/[\t|]/);
    const where = `export line ${String(k + 1)}`;
    if (cols.length !== 3) throw new BaselineError(`${where}: expected version, name, checksum`);
    const [v = "", name = "", checksum = ""] = cols;
    if (!/^[1-9][0-9]*$/.test(v)) throw new BaselineError(`${where}: the version must be a positive whole number`);
    if (!/^[0-9a-f]{64}$/.test(checksum)) throw new BaselineError(`${where}: the checksum must be 64 lower-case hex characters`);
    if (rows.has(Number(v))) throw new BaselineError(`${where}: version ${v} twice`);
    rows.set(Number(v), { name, checksum });
  });
  if (rows.size === 0) throw new BaselineError("the export holds no ledger row — it read nothing");
  const out: string[] = [];
  let diffs = 0;
  for (const e of b.entries) {
    const r = rows.get(e.version);
    if (r === undefined) out.push(`  ✗ version ${String(e.version)} (${e.name}): not in the export`);
    else if (r.name !== e.name) out.push(`  ✗ version ${String(e.version)}: the export names ${r.name}, ledger.tsv ${e.name}`);
    else if (r.checksum !== e.checksum) out.push(`  ✗ version ${String(e.version)} (${e.name}): the checksum differs (export ${r.checksum.slice(0, 12)}…, ledger.tsv ${e.checksum.slice(0, 12)}…)`);
    else continue;
    diffs += 1;
  }
  const after = [...rows.keys()].filter((v) => v > b.head).length;
  const tail = after > 0 ? `; ${String(after)} version(s) after the baseline, not compared` : "";
  out.push(
    diffs === 0
      ? `✓ the export holds all ${String(b.head)} versions of ledger.tsv with equal names and checksums${tail}`
      : `✗ ${String(diffs)} of the baseline's ${String(b.head)} versions differ from the export${tail}`,
  );
  return { exitCode: diffs === 0 ? 0 : 1, lines: out };
}
